const __pageData = JSON.parse('{"title":"会话技术与JWT令牌","description":"登录校验的第一块拼图「登录标记」——先想清楚登录校验要解决的两件事（登录标记 + 统一拦截），再对比三种会话跟踪方案（Cookie、Session、令牌）的原理与优缺点，然后拆开 JWT 令牌的三段结构看签名怎么防篡改，最后用 jjwt 把令牌的生成与解析写进工具类、接进登录接口，附过期令牌报 ExpiredJwtException 与 Cookie、Session 传递的真机实测","frontmatter":{"title":"会话技术与JWT令牌","published":"2026-09-29T00:00:00.000Z","description":"登录校验的第一块拼图「登录标记」——先想清楚登录校验要解决的两件事（登录标记 + 统一拦截），再对比三种会话跟踪方案（Cookie、Session、令牌）的原理与优缺点，然后拆开 JWT 令牌的三段结构看签名怎么防篡改，最后用 jjwt 把令牌的生成与解析写进工具类、接进登录接口，附过期令牌报 ExpiredJwtException 与 Cookie、Session 传递的真机实测","tags":["JavaWeb","HTTP","后端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-82-session-jwt.webp","order":82,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/82-会话技术与JWT令牌.md","filePath":"posts/学习文档/JavaWeb学习笔记/82-会话技术与JWT令牌.md"}');
